import{_ as t,o as s,c as a,a7 as i}from"./chunks/framework.C4ZIv4ii.js";const k=JSON.parse('{"title":"Shop Plugin & Templates","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/shop-plugin.md","filePath":"ecommerce/shop-plugin.md","lastUpdated":1791291593000}'),o={name:"ecommerce/shop-plugin.md"};function n(h,e,l,d,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="shop-plugin-templates" tabindex="-1">Shop Plugin &amp; Templates <a class="header-anchor" href="#shop-plugin-templates" aria-label="Permalink to &quot;Shop Plugin &amp; Templates&quot;">​</a></h1><p>The store ships with FalconCMS as a bundled plugin, <strong>Falcon Shop</strong> (<code>falcon-shop</code>). It is free, it is <strong>on by default</strong> — on a new install and on every site that updates — and it can be switched off like any other plugin.</p><h2 id="switching-the-shop-off" tabindex="-1">Switching the shop off <a class="header-anchor" href="#switching-the-shop-off" aria-label="Permalink to &quot;Switching the shop off&quot;">​</a></h2><p><strong>Admin → Plugins → Falcon Shop → Deactivate.</strong> With the shop off:</p><ul><li>No shop code runs and none of its CSS or JavaScript loads, in the storefront or the admin.</li><li>The Shop and Products menus leave the admin sidebar, and their screens answer 404. The dashboard and every other screen work as before.</li><li>Products, orders, customers and settings stay in the database untouched. Switch the shop back on and everything is where you left it.</li><li>Products are not served, and they are left out of search and the sitemap.</li><li><code>/cart</code>, <code>/checkout</code> and the other shop URLs behave as though there had never been a shop: a page of your own with that slug shows, otherwise the theme&#39;s 404. The pages you assigned as Shop, Cart, Checkout and Account are shown as ordinary pages.</li><li>A theme that calls <code>route(&#39;shop.cart&#39;)</code> keeps working, because the shop&#39;s route names still resolve while it is off.</li></ul><p>To force it off from the server, for example while you investigate a problem, add this to <code>.env</code>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">FALCON_DISABLED_PLUGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">falcon-shop</span></span></code></pre></div><p>This overrides the setting in the admin. Remove the line to hand control back to the admin. After you change <code>.env</code>, run <code>php artisan optimize:clear</code>, as you would for any other <code>.env</code> change. A cached configuration won&#39;t see the new value, and cached pages still show the shop&#39;s cart icon. If the CMS finds a route cache that was built with the shop in the other state, it deletes that cache itself.</p><p>A bundled plugin cannot be uninstalled, and it updates along with the CMS.</p><h2 id="theme-integration" tabindex="-1">Theme integration <a class="header-anchor" href="#theme-integration" aria-label="Permalink to &quot;Theme integration&quot;">​</a></h2><p>Add the shop to a theme with two hooks in its layout. The shop fills them while it is on, and they print nothing while it is off:</p><div class="language-blade vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">blade</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">{{-- in the header, next to the search or account icon: the cart icon and its count --}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?php </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_falcon_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;falcon_header_actions&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); ?&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">{{-- just before &lt;/body&gt;: the slide-out mini-cart --}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?php </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">do_falcon_action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;falcon_after_footer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); ?&gt;</span></span></code></pre></div><p>If a theme has no <code>falcon_after_footer</code>, the mini-cart is added at <code>falcon_footer</code> instead.</p><p>Anything else in a theme that belongs to the shop needs a check first:</p><div class="language-blade vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">blade</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@if </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">falcon_plugin_active</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;falcon-shop&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(&#39;shop.wishlist&#39;) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Wishlist&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@endif</span></span></code></pre></div><h2 id="customising-shop-templates" tabindex="-1">Customising shop templates <a class="header-anchor" href="#customising-shop-templates" aria-label="Permalink to &quot;Customising shop templates&quot;">​</a></h2><p>A theme overrides a shop template by holding its own copy at the same path. The shop looks in the active theme first, then in its parent theme, and finally uses its own template:</p><table tabindex="0"><thead><tr><th>Template</th><th>Page</th></tr></thead><tbody><tr><td><code>archive-product</code></td><td>Shop page and product category / tag archives</td></tr><tr><td><code>single-product</code></td><td>A simple product</td></tr><tr><td><code>single-product-variable</code></td><td>A variable product</td></tr><tr><td><code>ecommerce/cart</code></td><td>Cart</td></tr><tr><td><code>ecommerce/checkout</code></td><td>Checkout</td></tr><tr><td><code>ecommerce/confirmation</code></td><td>Order confirmation</td></tr><tr><td><code>ecommerce/account</code></td><td>Customer account</td></tr><tr><td><code>ecommerce/track-order</code></td><td>Order tracking</td></tr><tr><td><code>ecommerce/wishlist</code></td><td>Wishlist</td></tr><tr><td><code>ecommerce/mini-cart-items</code></td><td>The lines inside the mini-cart</td></tr></tbody></table><p>Copy one into the theme with the command and edit the copy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop:template</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # every template, and which ones the theme overrides</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop:template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ecommerce/cart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # copy the cart into the active theme</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop:template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --theme=aurora</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # into another theme (&quot;cart&quot; is enough)</span></span></code></pre></div><p>The command will not replace a copy that already exists unless you pass <code>--force</code>. Doing that throws away your changes to that copy.</p><p><code>php artisan make:theme my-theme --shop</code> creates a theme that already has a copy of every template.</p><h3 id="keeping-copies-up-to-date" tabindex="-1">Keeping copies up to date <a class="header-anchor" href="#keeping-copies-up-to-date" aria-label="Permalink to &quot;Keeping copies up to date&quot;">​</a></h3><p>Every shop template starts with a version line:</p><div class="language-blade vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">blade</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">{{-- @version 1.0.0 --}}</span></span></code></pre></div><p>When a release changes a template in a way your copy has to follow, such as a new checkout field or a renamed variable, that number goes up. If your copy carries an older number, or has no version line at all, <strong>Settings → Site Health</strong> lists it as outdated, and so does <code>php artisan shop:template</code>. Compare your copy with the current template and carry your changes across. Keep the version line in your copy, and set it to the version you brought it up to.</p><h2 id="for-developers" tabindex="-1">For developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For developers&quot;">​</a></h2><ul><li>The shop&#39;s PHP classes live under the <code>FalconShop\\</code> namespace in <code>vendor/falconcms/falconcms/plugins/falcon-shop/src</code>. Their old <code>FalconCms\\Core\\...</code> names still work, so code written against them does not need to change.</li><li>The models (<code>Order</code>, <code>Product</code> and the rest) and the database migrations remain in the core.</li><li>The shop&#39;s helper functions (<code>falcon_shipping_methods()</code>, <code>falcon_active_promotions()</code> and the rest) exist only while the shop is on, so check <code>falcon_plugin_active(&#39;falcon-shop&#39;)</code> before calling one. The exceptions are the ones themes commonly call, and these return safe empty values while the shop is off instead of failing: <ul><li><code>get_falcon_cart_url()</code></li><li><code>get_falcon_cart_subtotal()</code>, <code>get_falcon_cart_total()</code>, <code>get_falcon_cart_shipping()</code>, <code>get_falcon_cart_tax()</code>, <code>get_falcon_cart_shipping_details()</code></li><li><code>get_falcon_coupon_discount_amount()</code></li><li><code>falcon_related_products()</code>, <code>falcon_linked_products()</code>, <code>falcon_cart_cross_sells()</code></li></ul></li><li>Plugin assets are served from <code>/plugin-assets/{slug}/{path}</code>. Build the URL with <code>falcon_plugin_asset(&#39;falcon-shop&#39;, &#39;frontend/css/wishlist.css&#39;)</code>.</li></ul>`,28)])])}const g=t(o,[["render",n]]);export{k as __pageData,g as default};
